$rows=$pdo->query("SELECT * FROM notifications WHERE recipient_role='admin' AND recipient_id IS NULL ORDER BY id DESC LIMIT 200")->fetchAll();$pageTitle='Thông báo';require __DIR__.'/../includes/header.php';require __DIR__.'/_nav.php';
?>
<h1 class="h3">Thông báo quản trị</h1><form method="post" class="mb-3"><?= csrf_field() ?><input type="hidden" name="action" value="all"><button class="btn btn-outline-success btn-sm">Đánh dấu tất cả đã đọc</button></form>
